import { utcDate } from "./core/dates.js";
import { ContractViolationError } from "./core/errors.js";
import {
  decodeOrderCancelled,
  decodeOrderPlaced,
  type OrderCancelledEvent,
  type OrderPlacedEvent,
} from "./core/events.js";
import type { DataLake } from "./core/ports.js";
import type { CancellationRow, OrderLineRow, OrderRow } from "./core/rows.js";

/** `OrderPlaced` -> row of table `orders`. */
export function toOrderRow(event: OrderPlacedEvent): OrderRow {
  return {
    order_id: event.orderId,
    placed_date: utcDate(event.placedAt),
    channel: event.channel,
    currency: event.currency,
    units: event.lines.reduce((total, line) => total + line.qty, 0),
  };
}

/** `OrderPlaced` -> rows of table `order_lines`; lines that repeat a SKU are summed. */
export function toLineRows(event: OrderPlacedEvent): OrderLineRow[] {
  const unitsBySku = new Map<string, number>();
  for (const line of event.lines) {
    unitsBySku.set(line.sku, (unitsBySku.get(line.sku) ?? 0) + line.qty);
  }
  return [...unitsBySku].map(([sku, units]) => ({ order_id: event.orderId, sku, units }));
}

/** `OrderCancelled` -> row of table `order_cancellations`. */
export function toCancellationRow(event: OrderCancelledEvent): CancellationRow {
  return { order_id: event.orderId, cancelled_date: utcDate(event.cancelledAt) };
}

/** Validates and ingests one `OrderPlaced` event. Rejects, writing nothing, when the event breaks the contract. */
export async function ingestOrderPlaced(lake: DataLake, raw: unknown): Promise<OrderRow> {
  const event = decodeOrderPlaced(raw);
  const row = toOrderRow(event);
  await lake.upsertOrder(row, toLineRows(event));
  return row;
}

/** Validates and ingests one `OrderCancelled` event. */
export async function ingestOrderCancelled(lake: DataLake, raw: unknown): Promise<CancellationRow> {
  const row = toCancellationRow(decodeOrderCancelled(raw));
  await lake.upsertCancellation(row);
  return row;
}

export type IngestResult =
  | { readonly kind: "OrderPlaced"; readonly row: OrderRow }
  | { readonly kind: "OrderCancelled"; readonly row: CancellationRow };

/** Routes an event by its `type` field. Unknown types are rejected rather than dropped silently. */
export async function ingestEvent(lake: DataLake, raw: unknown): Promise<IngestResult> {
  const type = typeof raw === "object" && raw !== null ? (raw as { type?: unknown }).type : undefined;
  switch (type) {
    case "OrderPlaced":
      return { kind: "OrderPlaced", row: await ingestOrderPlaced(lake, raw) };
    case "OrderCancelled":
      return { kind: "OrderCancelled", row: await ingestOrderCancelled(lake, raw) };
    default:
      throw new ContractViolationError("event", [`type: expected OrderPlaced or OrderCancelled, got ${JSON.stringify(type)}`]);
  }
}
import type { Channel } from "./events.js";

/** Table `orders`: one row per placed order. */
export interface OrderRow {
  readonly order_id: string;
  /** UTC calendar date of `placedAt`, `YYYY-MM-DD`. */
  readonly placed_date: string;
  readonly channel: Channel;
  readonly currency: string;
  /** Total quantity over all lines. */
  readonly units: number;
}

/** Table `order_lines`: one row per order line. */
export interface OrderLineRow {
  readonly order_id: string;
  readonly sku: string;
  readonly units: number;
}

/** Table `order_cancellations`: one row per cancelled order. */
export interface CancellationRow {
  readonly order_id: string;
  readonly cancelled_date: string;
}

export interface LakeTables {
  readonly orders: OrderRow;
  readonly order_lines: OrderLineRow;
  readonly order_cancellations: CancellationRow;
}

export type TableName = keyof LakeTables;

export const TABLE_NAMES: readonly TableName[] = ["orders", "order_lines", "order_cancellations"];
import assert from "node:assert/strict";
import { describe, it } from "node:test";
import { ContractViolationError, createAnalyticsIngest } from "../src/index.js";
import { parseIsoInstant } from "../src/core/dates.js";

function placed(overrides: Record<string, unknown> = {}): Record<string, unknown> {
  return {
    type: "OrderPlaced",
    schemaVersion: 3,
    orderId: "ord-1",
    customerId: "cust-1",
    customerEmail: "jane@example.com",
    placedAt: "2026-10-10T23:30:00.000Z",
    channel: "web",
    currency: "USD",
    totalCents: 2497,
    lines: [
      { sku: "CAB-1", qty: 3, unitPriceCents: 499 },
      { sku: "ADP-1", qty: 1, unitPriceCents: 1000 },
    ],
    ...overrides,
  };
}

function cancelled(overrides: Record<string, unknown> = {}): Record<string, unknown> {
  return {
    type: "OrderCancelled",
    schemaVersion: 1,
    orderId: "ord-1",
    customerId: "cust-1",
    cancelledAt: "2026-10-11T08:00:00.000Z",
    ...overrides,
  };
}

function without(event: Record<string, unknown>, field: string): Record<string, unknown> {
  const copy = { ...event };
  delete copy[field];
  return copy;
}

describe("OrderPlaced ingestion", () => {
  it("writes an orders row and one order_lines row per SKU", async () => {
    const app = createAnalyticsIngest();
    const row = await app.ingestOrderPlaced(placed());
    assert.deepEqual(row, { order_id: "ord-1", placed_date: "2026-10-10", channel: "web", currency: "USD", units: 4 });
    assert.deepEqual(await app.rows("orders"), [row]);
    assert.deepEqual(await app.rows("order_lines"), [
      { order_id: "ord-1", sku: "CAB-1", units: 3 },
      { order_id: "ord-1", sku: "ADP-1", units: 1 },
    ]);
  });

  it("uses the UTC date and accepts offsets", async () => {
    const app = createAnalyticsIngest();
    const row = await app.ingestOrderPlaced(placed({ placedAt: "2026-10-11T01:30:00+02:00" }));
    assert.equal(row.placed_date, "2026-10-10");
  });

  it("is idempotent: a redelivered event replaces its rows", async () => {
    const app = createAnalyticsIngest();
    await app.ingestOrderPlaced(placed());
    await app.ingestOrderPlaced(placed({ lines: [{ sku: "CAB-1", qty: 1, unitPriceCents: 499 }] }));
    assert.equal((await app.rows("orders")).length, 1);
    assert.deepEqual(await app.rows("order_lines"), [{ order_id: "ord-1", sku: "CAB-1", units: 1 }]);
  });

  it("sums lines that repeat a SKU", async () => {
    const app = createAnalyticsIngest();
    await app.ingestOrderPlaced(placed({ lines: [{ sku: "A", qty: 1 }, { sku: "A", qty: 2 }] }));
    assert.deepEqual(await app.rows("order_lines"), [{ order_id: "ord-1", sku: "A", units: 3 }]);
  });
});

